// Produces the macOS half of a release's `manifest.json` from the Electrobun build: the built
// `Obol.app` zipped under the release name (`obol-<v>-macos-<arch>.zip`), its sha256, and a
// `mac.<arch>` entry. The Homebrew cask (generated by `brew-cask.ts`) reads the merged manifest.
//
// Besides the custom zip/manifest, each leg also copies Electrobun's own stable updater pair out
// of `desktop/artifacts/` (files unchanged, under their Electrobun names):
//   macOS:   stable-macos-<arch>-update.json + stable-macos-<arch>-<App>.app.tar.zst
//   Windows: stable-win-x64-update.json      + stable-win-x64-<App>.tar.zst
// `update.json` carries the version and artifact filename. The download base URL is embedded in
// the built app's generated Electrobun config, not in this JSON. A missing file fails the leg.
//
// The release workflow runs this once per macOS runner (after `bun run eb:build` and the
// `codesign --verify` gate) and merges the two halves. The manifest records each archive's exact
// sha256 and version for the cask and release page.
//
// Platforms: `--platform windows --arch x64` runs on the native Windows x64 runner, re-emits
// Electrobun's `artifacts/win-x64-<App>-Setup.zip` under the
// release-asset name (`obol-<v>-windows-x64-setup.zip`) plus a `.sha256` sidecar, and publishes
// no manifest: the Windows setup asset is uploaded as-is beside the macOS assets.
//
// One command, run from `desktop/`:
//   bun scripts/eb-publish.ts build --arch <arm64|x86_64> --version <v> --base-url <url> \
//     [--notes-file <path>] [--build-root build] [--app Obol.app] [--out dist/publish]
// or, on Windows:
//   bun scripts/eb-publish.ts build --platform windows --arch x64 --version <v> --base-url <url> \
//     [--out dist/publish]
//
// Without `--version` the version comes from the `version` key of `desktop/app.json` (falling
// back to the repository-root `app.json`), the same source the release workflows gate on.
import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { basename, dirname, join, resolve } from 'node:path';

/** The architectures the release pipeline publishes. Electrobun spells `x86_64` as `x64` in
 * build directory and artifact names; the release assets use the long form. */
type UpdateArch = 'arm64' | 'x86_64';
const UPDATE_ARCHES: readonly UpdateArch[] = ['arm64', 'x86_64'] as const;

/** One macOS artifact of a release: where it is and what its bytes must hash to. */
interface UpdateManifestEntry {
  url: string;
  /** Lowercase hex sha256 of the archive at `url`. */
  sha256: string;
}

/**
 * The wire format of the release `manifest.json`. Only `version`, `notes` and `mac` are
 * published; the release workflow's merge job adds the top-level `url`/`sha256` (the arm64 zip)
 * on top for readers that precede the `mac` block.
 */
interface UpdateManifest {
  version: string;
  notes: string | null;
  mac: Partial<Record<UpdateArch, UpdateManifestEntry>>;
}

/** The file the merge job reads from each macOS leg (`dist/publish/manifest.json`). */
const MANIFEST_NAME = 'manifest.json';

/** Release-asset prefix: `obol-<v>-macos-<arch>.zip`. */
const ARTIFACT_PREFIX = 'obol';

/** Electrobun names its build directories `x64`; the release assets use `x86_64`. */
const ELECTROBUN_ARCH: Record<UpdateArch, string> = { arm64: 'arm64', x86_64: 'x64' };

const SHA256_PATTERN = /^[0-9a-f]{64}$/i;

export function isArch(value: string): value is UpdateArch {
  return (UPDATE_ARCHES as readonly string[]).includes(value);
}

/** `--platform` selects the artifact family; macOS keeps the manifest flow, Windows does not. */
export type Platform = 'macos' | 'windows';
const PLATFORMS: readonly Platform[] = ['macos', 'windows'] as const;

export function isPlatform(value: string): value is Platform {
  return (PLATFORMS as readonly string[]).includes(value);
}

/** `x64` is the runtime's spelling; the manifest and the archives use `x86_64`. */
export function normalizeArch(value: string): UpdateArch | null {
  if (value === 'x64') return 'x86_64';
  return isArch(value) ? value : null;
}

/** `release.yml`'s version gate, the form the manifest and the tag must carry. */
export function normalizeVersion(value: string): string | null {
  const text = value.trim();
  return /^[0-9]+\.[0-9]+\.[0-9]+[a-z]*([-+][0-9A-Za-z.-]+)?$/.test(text) ? text : null;
}

export function artifactName(version: string, arch: UpdateArch): string {
  return `${ARTIFACT_PREFIX}-${version}-macos-${arch}.zip`;
}

/**
 * Shared contract with the release workflow: the Windows setup asset rides beside the macOS
 * assets without a manifest (`eb-publish.ts build --platform windows --arch x64`).
 */
export function windowsSetupName(version: string): string {
  return `${ARTIFACT_PREFIX}-${version}-windows-x64-setup.zip`;
}

/** Electrobun's stable Windows output for the x64 runner: `artifacts/win-x64-<App>-Setup.zip`. */
function electrobunSetupZip(): string {
  return resolve(join(import.meta.dir, '..', 'artifacts', `win-x64-${appName()}-Setup.zip`));
}

/**
 * Electrobun emits `stable-<rest>-update.json` metadata and the matching full tar under
 * `desktop/artifacts/`. The app's generated config embeds `release.baseUrl`; the JSON keeps
 * Electrobun's version/artifact schema and the pair is copied unchanged so the updater can fetch
 * both from that base. `<App>` is the app name from `app.json`.
 */
function updaterArtifactNames(platform: 'macos' | 'windows', arch: UpdateArch): readonly [string, string] {
  const ebArch = ELECTROBUN_ARCH[arch];
  return platform === 'macos'
    ? [`stable-macos-${ebArch}-update.json`, `stable-macos-${ebArch}-${appName()}.app.tar.zst`]
    : [`stable-win-x64-update.json`, `stable-win-x64-${appName()}.tar.zst`];
}

/**
 * Copies the Electrobun updater pair into the publish output unchanged. A missing file means the
 * packaged app would have no update channel: the leg must fail, not publish a half-channel.
 */
function copyUpdaterArtifacts(platform: 'macos' | 'windows', arch: UpdateArch, out: string): readonly string[] {
  return updaterArtifactNames(platform, arch).map((name) => {
    const source = resolve(join(import.meta.dir, '..', 'artifacts', name));
    if (!existsSync(source)) {
      throw new Error(`Electrobun built no updater artifact ${name} at ${source}; run bun run eb:build first`);
    }
    const target = join(out, name);
    copyFileSync(source, target);
    return target;
  });
}

/**
 * Electrobun names the Windows installer after the app `name` of `app.json` (ASCII spaces
 * removed); the same file the version default comes from.
 */
function appName(): string {
  const here = join(process.cwd(), 'app.json');
  const repoRoot = join(dirname(import.meta.dir), '..', 'app.json');
  for (const path of [here, repoRoot].filter(existsSync)) {
    try {
      const raw = JSON.parse(readFileSync(path, 'utf8')) as Record<string, unknown>;
      const name = typeof raw.name === 'string' && raw.name !== '' ? raw.name.replace(/ /g, '') : null;
      if (name !== null) return name;
    } catch {
      // fall through to the next candidate
    }
  }
  return 'Obol';
}

interface WindowsZipListing {
  names: readonly string[];
  setupExecutableName: string | null;
}

function nativeWindowsTar(): string {
  const systemRoot = process.env.SystemRoot || 'C:\\Windows';
  const tar = join(systemRoot, 'System32', 'tar.exe');
  if (!existsSync(tar)) {
    throw new Error(`Windows native tar not found at ${tar} (System32 tar.exe is required for Windows paths)`);
  }
  return tar;
}

/**
 * Windows' own tar.exe (shipped in System32) lists zip members; the archive path travels as a
 * spawn argv element, never through a shell, so nothing in it can be reinterpreted as a command.
 */
function listWindowsZip(setupZip: string, errorPrefix: string): WindowsZipListing {
  const tar = nativeWindowsTar();
  const listing = Bun.spawnSync([tar, '-tf', setupZip], { stdout: 'pipe', stderr: 'pipe' });
  const lines = listing.stdout.toString().split(/\r?\n/).map((name) => name.trim()).filter((name) => name !== '');
  if (listing.exitCode !== 0 || lines.length === 0) {
    throw new Error(`${errorPrefix}: the archive is unreadable: ${listing.stderr.toString().trim()}`);
  }
  const names = lines.filter((name) => !name.endsWith('/'));
  const app = appName().toLowerCase();
  const setupExecutableName =
    names.find((entry) => entry.toLowerCase().endsWith('.exe') && entry.toLowerCase().includes(app)) ?? null;
  return { names, setupExecutableName };
}

/**
 * Refuses an archive without the visible setup executable or without its adjacent hidden
 * installer payload: a truncated Electrobun output would publish a release whose installer
 * opens with a missing payload.
 */
function checkSetupZip(listing: WindowsZipListing): void {
  if (listing.setupExecutableName === null) {
    throw new Error(`the archive has no ${appName()} *.exe setup executable`);
  }
  if (listing.names.length - 1 < 1) {
    throw new Error(`the archive has no installer payload beside ${listing.setupExecutableName}`);
  }
}

/** `https://…/download` + `obol-….zip` → the address the manifest carries. */
export function downloadUrl(baseUrl: string, file: string): string {
  const url = new URL(baseUrl);
  if (url.protocol !== 'https:' && url.protocol !== 'http:') {
    throw new Error('--base-url must be http(s)');
  }
  if (url.username !== '' || url.password !== '') {
    throw new Error('--base-url must not carry credentials');
  }
  return `${baseUrl.replace(/\/+$/, '')}/${file}`;
}

function record(value: unknown): Record<string, unknown> | null {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null;
  return value as Record<string, unknown>;
}

function parseEntry(value: unknown): UpdateManifestEntry | null {
  const fields = record(value);
  if (fields === null) return null;
  const url = fields.url;
  const sha256 = fields.sha256;
  if (typeof url !== 'string' || !SHA256_PATTERN.test(typeof sha256 === 'string' ? sha256 : '')) {
    return null;
  }
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return null;
  }
  if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') return null;
  if (parsed.username !== '' || parsed.password !== '') return null;
  return { url: parsed.toString(), sha256: (sha256 as string).toLowerCase() };
}

/**
 * Validates a manifest half: a bad digest, a bad url or a missing arch block is not an artifact
 * to offer. A half without at least one macOS artifact (or without a version) is refused.
 */
export function parseManifest(raw: unknown): UpdateManifest {
  const fields = record(raw);
  if (fields === null) throw new Error('the manifest is not an object');
  const version = fields.version;
  if (
    typeof version !== 'string' ||
    normalizeVersion(version) === null
  ) {
    throw new Error('the manifest has no valid version');
  }
  const rawNotes = fields.notes;
  if (rawNotes !== undefined && rawNotes !== null && typeof rawNotes !== 'string') {
    throw new Error('the manifest notes are not a string');
  }
  const notes = typeof rawNotes === 'string' ? rawNotes : null;
  const macField = record(fields.mac);
  if (macField === null) throw new Error('the manifest has no mac block');
  const mac: Partial<Record<UpdateArch, UpdateManifestEntry>> = {};
  let published = 0;
  for (const arch of UPDATE_ARCHES) {
    const value = macField[arch];
    if (value === undefined) continue;
    const entry = parseEntry(value);
    if (entry === null) throw new Error(`the manifest mac.${arch} entry is not valid`);
    mac[arch] = entry;
    published += 1;
  }
  if (published === 0) throw new Error('the manifest has no mac artifacts');
  return { version: version.trim(), notes, mac };
}

/**
 * One runner's half of the release `manifest.json`. The merge job combines the two macOS halves;
 * a half that does not parse is not written at all.
 */
export function buildManifestHalf(input: {
  version: string;
  notes: string;
  arch: UpdateArch;
  url: string;
  sha256: string;
}): UpdateManifest {
  return parseManifest({
    version: input.version,
    notes: input.notes,
    mac: { [input.arch]: { url: input.url, sha256: input.sha256 } },
  });
}

/**
 * `release.yml`'s `sed '/^Merge pull request #/,/^$/d'`: GitHub's merge header (and the blank
 * line after it) is not news for anyone. A header without a following blank line drops the rest,
 * as sed does — the notes never survive a malformed commit body intact, and publishing one line
 * of noise is worse than falling back.
 */
export function stripMergeHeader(text: string): string {
  const kept: string[] = [];
  let dropping = false;
  for (const line of text.split('\n')) {
    if (!dropping && line.startsWith('Merge pull request #')) {
      dropping = true;
      continue;
    }
    if (dropping) {
      if (line === '') dropping = false;
      continue;
    }
    kept.push(line);
  }
  return kept.join('\n');
}

/**
 * The body of the `Release <version>:` commit, as release.yml publishes it; `null` when none of
 * the messages carries the header. `version` is escaped, so a pre-release such as `1.0.0-rc.1`
 * matches itself and not another commit's body.
 */
export function releaseNotesFrom(messages: readonly string[], version: string): string | null {
  // `m`: git's `--grep` matches a line, not only the body's first line (release.yml's rule).
  const pattern = new RegExp(`^Release ${version.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}:`, 'm');
  for (const message of messages) {
    if (!pattern.test(message)) continue;
    const notes = stripMergeHeader(message).trim();
    return notes === '' ? null : notes;
  }
  return null;
}

/** The one `.app` in `build/stable-macos-<arch>` (stable builds carry no channel suffix). */
export function findBuiltApp(buildRoot: string, arch: UpdateArch): string | null {
  const directory = join(buildRoot, `stable-macos-${ELECTROBUN_ARCH[arch]}`);
  if (!existsSync(directory)) return null;
  const apps = readdirSync(directory, { withFileTypes: true }).filter(
    (entry) => entry.isDirectory() && entry.name.endsWith('.app'),
  );
  return apps.length === 1 ? join(directory, apps[0].name) : null;
}

export async function sha256File(path: string): Promise<string> {
  const hasher = new Bun.CryptoHasher('sha256');
  for await (const chunk of Bun.file(path).stream()) hasher.update(chunk);
  return hasher.digest('hex');
}

const ARCHIVE_SAFE_LISTING = 'Contents/Info.plist';

/**
 * `ditto -c -k --keepParent` — the zip format a macOS bundle is published with and that an
 * updater extracts with `ditto -x -k` before it looks for the single `.app` it swaps.
 */
function createArchive(app: string, target: string): void {
  const result = Bun.spawnSync(['/usr/bin/ditto', '-c', '-k', '--keepParent', app, target], {
    stdout: 'ignore',
    stderr: 'pipe',
  });
  if (result.exitCode !== 0) {
    throw new Error(`ditto could not create the archive: ${result.stderr.toString().trim()}`);
  }
}

/**
 * Refuses an archive without a bundle in it: a zip of the wrong directory would publish a
 * release whose install fails on every machine after the person waited for the download.
 */
function verifyArchive(target: string): void {
  const listing = Bun.spawnSync(['/usr/bin/unzip', '-l', target], { stdout: 'pipe', stderr: 'pipe' });
  if (listing.exitCode !== 0) {
    throw new Error(`the archive is unreadable: ${listing.stderr.toString().trim()}`);
  }
  const names = listing.stdout.toString();
  if (!names.split('\n').some((line) => line.trimEnd().endsWith(ARCHIVE_SAFE_LISTING))) {
    throw new Error(`the archive has no ${ARCHIVE_SAFE_LISTING}; was the .app built?`);
  }
}

/** Reads one string out of an XML `Info.plist`; `null` when the key is absent or not a string. */
export function plistString(xml: string, key: string): string | null {
  const escaped = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const match = new RegExp(`<key>\\s*${escaped}\\s*</key>\\s*<string>([^<]*)</string>`).exec(xml);
  return match === null ? null : decodeXmlEntities(match[1]).trim();
}

function decodeXmlEntities(text: string): string {
  const map: Record<string, string> = {
    '&lt;': '<',
    '&gt;': '>',
    '&quot;': '"',
    '&apos;': "'",
    '&amp;': '&',
  };
  return text.replace(/&(?:lt|gt|quot|apos|amp);/g, (entity) => map[entity] ?? entity);
}

/**
 * The bundle must already carry the version the release will claim. Electrobun writes the
 * config's version to `Resources/version.json` (what its own updater reads); the plist is the
 * fallback, and macOS may not preserve hotfix letters there.
 */
function verifyBundleVersion(app: string, version: string): void {
  let plist: string;
  try {
    plist = readFileSync(join(app, 'Contents', 'Info.plist'), 'utf8');
  } catch {
    throw new Error(`${app} is not an app bundle (no Contents/Info.plist)`);
  }
  let buildVersion: string | null = null;
  try {
    const meta = JSON.parse(
      readFileSync(join(app, 'Contents', 'Resources', 'version.json'), 'utf8'),
    ) as { version?: unknown };
    buildVersion = typeof meta.version === 'string' ? meta.version : null;
  } catch {
    buildVersion = null;
  }
  const bundleVersion =
    buildVersion ?? plistString(plist, 'CFBundleShortVersionString') ?? plistString(plist, 'CFBundleVersion');
  if (bundleVersion === null) throw new Error(`${app} has no bundle version`);
  if (bundleVersion.replace(/^v/, '') !== version.replace(/^v/, '')) {
    throw new Error(
      `${app} says version ${bundleVersion}, but --version says ${version}; the Electrobun build must take the version from desktop/app.json`,
    );
  }
}

function gitBody(args: readonly string[]): string | null {
  const result = Bun.spawnSync(['git', ...args], { stdout: 'pipe', stderr: 'ignore' });
  if (result.exitCode !== 0) return null;
  const text = result.stdout.toString().trim();
  return text === '' ? null : text;
}

/** `--notes-file` from the workflow, or the same commit lookup release.yml does, or a last resort. */
function resolveNotes(version: string, notesFile: string | undefined): string {
  if (notesFile !== undefined) {
    const text = stripMergeHeader(readFileSync(notesFile, 'utf8')).trim();
    return text === '' ? `Obol ${version}` : text;
  }
  const matched = gitBody([
    'log',
    '-1',
    '--no-merges',
    '--extended-regexp',
    '--grep',
    `^Release ${version.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}:`,
    '--format=%B',
  ]);
  const last = gitBody(['log', '-1', '--format=%B']);
  const candidates = [matched, last].filter((value): value is string => value !== null);
  const notes = releaseNotesFrom(candidates, version) ?? stripMergeHeader(matched ?? last ?? '').trim();
  return notes === '' ? `Obol ${version}` : notes;
}

interface ParsedArgs {
  flags: Record<string, string>;
  rest: string[];
}

function parseArgs(argv: readonly string[]): ParsedArgs {
  const flags: Record<string, string> = {};
  const rest: string[] = [];
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (!arg.startsWith('--')) {
      rest.push(arg);
      continue;
    }
    const name = arg.slice(2);
    const value = argv[index + 1];
    if (name === '' || value === undefined || value.startsWith('--')) {
      throw new Error(`${arg} needs a value`);
    }
    flags[name] = value;
    index += 1;
  }
  return { flags, rest };
}

/** A typo in a release job must fail here, not quietly publish a default. */
function checkFlags(flags: Record<string, string>, allowed: readonly string[]): void {
  for (const name of Object.keys(flags)) {
    if (!allowed.includes(name)) throw new Error(`unknown option --${name}`);
  }
}

/**
 * The default version: the `version` key of `app.json`. In a release job the working directory
 * is `desktop/`, where the app manifest lives; a run from the repository root falls back to it.
 */
function baseVersion(): string {
  const here = join(process.cwd(), 'app.json');
  const repoRoot = join(dirname(import.meta.dir), '..', 'app.json');
  const candidates = [here, repoRoot].filter(existsSync);
  if (candidates.length === 0) {
    throw new Error('no app.json beside desktop/ or here; pass --version');
  }
  let raw: unknown;
  try {
    raw = JSON.parse(readFileSync(candidates[0], 'utf8')) as unknown;
  } catch {
    throw new Error(`${candidates[0]} is not readable; pass --version`);
  }
  const version =
    typeof raw === 'object' && raw !== null ? (raw as Record<string, unknown>).version : undefined;
  if (typeof version !== 'string') throw new Error(`${candidates[0]} has no version`);
  return version;
}

function usage(): string {
  return [
    'usage:',
    '  bun scripts/eb-publish.ts build --version <v> --base-url <url>',
    '',
    '    mac (default): --arch <arm64|x86_64> [--notes-file <path>] [--build-root build]',
    '      [--app Obol.app] [--out dist/publish]',
    '    windows: --platform windows --arch x64 [--out dist/publish]',
  ].join('\n');
}

async function runBuild(argv: readonly string[]): Promise<void> {
  const { flags, rest } = parseArgs(argv);
  if (rest.length > 0) throw new Error(`unexpected argument: ${rest[0]}`);
  const platform = flags.platform ?? 'macos';
  if (!isPlatform(platform)) throw new Error(`--platform must be one of ${PLATFORMS.join(', ')}`);
  // A typo in a release job must fail here, not quietly publish a default: macos-only options are
  // refused on the Windows leg and vice versa.
  checkFlags(
    flags,
    platform === 'windows'
      ? ['platform', 'arch', 'version', 'base-url', 'out']
      : ['platform', 'arch', 'version', 'base-url', 'notes-file', 'build-root', 'app', 'out'],
  );
  const version = normalizeVersion(flags.version ?? baseVersion());
  if (version === null) throw new Error('--version must be X.Y.Z, X.Y.Z<letters>, or X.Y.Z-rc.N');
  if (platform === 'windows' && flags.arch !== 'x64') {
    throw new Error('--platform windows requires --arch x64 (the Windows release target)');
  }
  const baseUrl = flags['base-url'];
  if (baseUrl === undefined) throw new Error('--base-url is required (the release download directory)');

  const out = resolve(flags.out ?? 'dist/publish');
  mkdirSync(out, { recursive: true });

  if (platform === 'windows') return runWindowsBuild({ version, baseUrl, out });

  const archFlag = normalizeArch(flags.arch ?? (process.arch === 'x64' ? 'x86_64' : process.arch));
  if (archFlag === null) throw new Error(`--arch must be one of ${UPDATE_ARCHES.join(', ')} or x64`);
  const buildRoot = resolve(flags['build-root'] ?? 'build');
  const appPath = flags.app ?? findBuiltApp(buildRoot, archFlag);
  if (appPath === null) {
    throw new Error(
      `no .app under ${join(buildRoot, `stable-macos-${ELECTROBUN_ARCH[archFlag]}`)}; run bun run eb:build first`,
    );
  }
  const app = resolve(appPath);
  verifyBundleVersion(app, version);

  const target = join(out, artifactName(version, archFlag));
  createArchive(app, target);
  verifyArchive(target);

  // Electrobun's stable updater files ride beside the zip/manifest: the in-app updater fetches
  // them from the release's `baseUrl` (update.json → matching tar.zst), under Electrobun's names.
  const updater = copyUpdaterArtifacts('macos', archFlag, out);

  const sha256 = await sha256File(target);
  const notes = resolveNotes(version, flags['notes-file']);
  const manifest = buildManifestHalf({
    version,
    notes,
    arch: archFlag,
    url: downloadUrl(baseUrl, basename(target)),
    sha256,
  });
  const manifestPath = join(out, MANIFEST_NAME);
  writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
  console.log(`artifact: ${target}`);
  console.log(`sha256:   ${sha256}`);
  console.log(`manifest: ${manifestPath}`);
  for (const file of updater) console.log(`updater:  ${file}`);
}

/**
 * The Windows leg, run on the native Windows x64 runner only: Electrobun's
 * `artifacts/win-x64-<App>-Setup.zip` is re-emitted under the release-asset name plus a
 * `<artifact>.sha256` sidecar. No manifest is written; `--base-url` is still part of the
 * contract and is validated here even though no manifest carries the address.
 */
async function runWindowsBuild(input: { version: string; baseUrl: string; out: string }): Promise<void> {
  if (process.platform !== 'win32') {
    throw new Error('the Windows publish must run on the native Windows x64 runner');
  }
  const setupZipSource = electrobunSetupZip();
  if (!existsSync(setupZipSource)) {
    throw new Error(
      `Electrobun built no Windows setup zip at ${setupZipSource}; run the Windows Electrobun build first`,
    );
  }
  const downloadAddress = downloadUrl(input.baseUrl, windowsSetupName(input.version));

  const target = join(input.out, windowsSetupName(input.version));
  copyFileSync(setupZipSource, target);
  checkSetupZip(listWindowsZip(target, `the re-emitted setup zip ${target}`));

  const sha256 = await sha256File(target);
  const sidecarPath = `${target}.sha256`;
  writeFileSync(sidecarPath, `${sha256}  ${windowsSetupName(input.version)}\n`);

  console.log(`artifact: ${target}`);
  console.log(`sha256:   ${sha256}`);
  console.log(`sidecar:  ${sidecarPath}`);
  console.log(`url:      ${downloadAddress}`);
  // The Windows leg copies the same Electrobun pair the macOS legs copy: the in-app updater on
  // a Windows install fetches `update.json` and the full tar from the release `baseUrl`.
  const updater = copyUpdaterArtifacts('windows', 'x86_64', input.out);
  for (const file of updater) console.log(`updater:  ${file}`);
}

async function main(): Promise<void> {
  const [command, ...argv] = process.argv.slice(2);
  if (command === 'build') return runBuild(argv);
  throw new Error(usage());
}

if (import.meta.main) {
  main().catch((error: unknown) => {
    console.error(`eb-publish: ${error instanceof Error ? error.message : String(error)}`);
    process.exit(1);
  });
}
